def _trim_partial_next_line_indent(text: str, end_pos: int) -> int:
    line_start = text.rfind("\n") + 1
    if line_start == 0:
        return end_pos

    suffix = text[line_start:]
    if suffix and suffix.strip(" \t") == "" and len(suffix.expandtabs(4)) < 4:
